for filename in ['OT_1997CHUNK5_NEUTRAL.md','OT_1997CHUNK5_NEUTRAL_A.md']:
    p=freeze/filename
    text=p.read_text(encoding='utf-8')
    for name,body in updates.items():
        start=text.index('# '+name+'\n')
        end=text.find('\n# ',start+len(name)+3)
        # The first following top-level heading is SECTION I, so use next case separator.
        end=text.find('\n\n# ',text.index('## E. SOURCES',start))
        if end<0: end=len(text)
        old=text[start:end]
        c=old.index('## C.')
        e=old.index('## E. SOURCES')
        new=old[:c]+body+'\n'+old[e:]
        if name=='Lewis v. United States':
            new=new.replace('* **Relief Requested:** Lewis argues that 18 U.S.C. §1111 already makes the conduct punishable, leaving no gap for §13 to fill.', '* **Relief Requested:** Lewis seeks relief from the mandatory life sentence while not contesting retention of the federal second-degree murder conviction on the jury findings; the assimilation question determines the governing sentencing scheme.')
            new=new.replace('* **Threshold, Preservation, and Vehicle Matters:** No acquittal of all homicide liability is implied. Verify the actual verdict before selecting the replacement judgment.', '* **Threshold, Preservation, and Vehicle Matters:** Conviction retention and sentence are distinct. The source-supported lack of challenge to the retained federal second-degree conviction and conditional Government resentencing concession constrain the remedy as set out below.')
        if name=='Glendora v. Porzio':
            a=new.index('* **Material Record:**')
            b=new.index('* **Threshold, Preservation',a)
            new=new[:a]+'''* **Material Record:** The recovered petition alleges that private participants in the landlord dispute used false service affidavits, that the state judge accepted them despite lack of personal jurisdiction, and that a service-contest hearing was denied. It disputes frivolousness and the appellate financial warning and challenges the form of the appellate order. The district court invoked judicial immunity, lack of private-party state action, insufficient conspiracy facts and its inability to review state judgments. The Second Circuit denied appellate financial leave and dismissed the appeal as frivolous. These are allegations and lower-court grounds, not findings by this Court. Source control's recovered petition and orders support the detailed account below; no historical Supreme Court filing action is adopted merely from a retrospective description.\n'''+new[b:]
        if name.startswith('Quality King'):
            new=new.replace('to reproduce and distribute the copyrighted material in the United States.', 'concerning distribution and importation of the copyrighted labels in the United States; no unauthorized reproduction of the labels is alleged in the source-corrected account.')
        new += '\n\n* **Clean source addendum:** [Objective facts and source status](../research/chunk5_control/NEUTRAL_SOURCE_FACTS.md). Same-matter Supreme Court source links are control-only; the independent model uses the sanitized facts, not the linked raw opinions.\n'
        text=text[:start]+new+text[end:]
    p.write_text(text,encoding='utf-8')

